package com.oracle.banking.branch.service;import com.oracle.banking.branch.dto.BranchDtos.*;import com.oracle.banking.branch.exception.ResourceNotFoundException;import com.oracle.banking.branch.repository.BranchRepository;import org.springframework.stereotype.Service;import java.util.*;@Service public class BranchService{private final BranchRepository r;public BranchService(BranchRepository r){this.r=r;}public List<Summary> all(){return r.findAll().stream().map(Summary::from).toList();}public Response byId(String id){return Response.from(r.findById(id).orElseThrow(()->new ResourceNotFoundException("Branch not found")));}public Response byIfsc(String i){return Response.from(r.findByIfsc(i).orElseThrow(()->new ResourceNotFoundException("Branch not found")));}}
